\begin{proposition}
\label{prop:8-33}

\uses{cor:8-31}




\dcref{ch8:8.33}
The Lie bracket of two smooth left-invariant vector fields on a Lie group is
left-invariant.
\end{proposition}

\begin{proof}

\sketch For every $g\in G$, Corollary~\ref{cor:8-31} gives
\[
(L_g)_*[X,Y]=[(L_g)_*X,(L_g)_*Y]=[X,Y].
\]
\end{proof}

